var t=`0716-moambe-chicken`;var i=`world-0716`;var a=`CD`;var o=`central-africa`;var s=4;var r=67;var l={en:`Moambe Chicken`,ua:`Курка муамбе`};var c={en:`Moambe Chicken is a Democratic Republic of the Congo classic prepared with chicken thigh, yellow onion, palm nut concentrate, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Курка муамбе, страва кухні країни Демократична Республіка Конго зі складниками: куряче стегно, жовта цибуля, концентрат пальмових плодів, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var h=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`chicken-thigh`,850,`g`],[`red-palm-oil`,55,`ml`],[`yellow-onion`,190,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 50 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 50 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:50,i:[[`palm-nut-concentrate`,240,`g`],[`water`,720,`ml`],[`tomato`,330,`g`],[`okra`,240,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:5,i:[[`garlic`,4,`clove`],[`table-salt`,null,`to_taste`]]}];var g={slug:t,id:i,country:`CD`,region:o,servings:4,minutes:67,title:l,text:c,steps:h};export{a as country,g as default,i as id,r as minutes,o as region,s as servings,t as slug,h as steps,c as text,l as title};